package com.salespunch360.mobile
import android.app.Application;import androidx.lifecycle.AndroidViewModel;import androidx.lifecycle.viewModelScope;import com.salespunch360.mobile.data.*;import java.io.IOException;import kotlinx.coroutines.flow.*;import kotlinx.coroutines.launch;import kotlinx.serialization.json.*
data class ProjectState(val loading:Boolean=false,val saving:Boolean=false,val query:String="",val status:String?=null,val rows:List<JsonObject> = emptyList(),val options:JsonObject=buildJsonObject{},val metrics:JsonObject=buildJsonObject{},val detail:JsonObject?=null,val costing:JsonObject?=null,val editing:JsonObject?=null,val error:String?=null,val budgetEditing:Boolean=false)
class AccountProjectViewModel(app:Application):AndroidViewModel(app){private val api=ApiClient(SecureSession(app));private suspend fun optionalCosting(id:String,options:JsonObject):JsonObject? = if(options["capabilities"]?.jsonObject?.get("costView")?.jsonPrimitive?.booleanOrNull==true)api.projectCosting(id) else null;private val _state=MutableStateFlow(ProjectState());val state:StateFlow<ProjectState> = _state;init{load()};fun load()=viewModelScope.launch{_state.value=_state.value.copy(loading=true,error=null);try{val x=api.projects(_state.value.query,_state.value.status);_state.value=_state.value.copy(loading=false,rows=x["rows"]?.jsonArray?.map{it.jsonObject}.orEmpty(),metrics=x["metrics"]?.jsonObject?:buildJsonObject{},options=api.projectOptions())}catch(e:Exception){fail(e)}};fun search(q:String){_state.value=_state.value.copy(query=q);load()};fun filter(v:String?){_state.value=_state.value.copy(status=v);load()};fun create(){_state.value=_state.value.copy(editing=buildJsonObject{})};fun action(id:String,action:String)=viewModelScope.launch{try{api.projectAction(id,action);open(id);load()}catch(e:Exception){fail(e)}};fun editBudget(v:Boolean=true){_state.value=_state.value.copy(budgetEditing=v)};fun saveBudget(id:String,lines:List<ProjectBudgetLineDraft>)=viewModelScope.launch{
if(_state.value.saving)return@launch
_state.value=_state.value.copy(saving=true,error=null)
try{val x=api.saveProjectBudget(id,projectBudgetPayload(lines));_state.value=_state.value.copy(detail=x,budgetEditing=false,saving=false,costing=optionalCosting(id,_state.value.options))}catch(e:Exception){fail(e)}};fun edit(){_state.value=_state.value.copy(editing=_state.value.detail)};fun close(){_state.value=_state.value.copy(editing=null,detail=null,costing=null)};fun open(id:String)=viewModelScope.launch{try{val options=api.projectOptions(id);_state.value=_state.value.copy(detail=api.project(id),costing=optionalCosting(id,options),options=options)}catch(e:Exception){fail(e)}};fun save(p:JsonObject)=viewModelScope.launch{try{val edit=_state.value.editing?.containsKey("id")==true;val x=api.saveProject(edit,p);_state.value=_state.value.copy(editing=null,detail=x,costing=optionalCosting(x["id"]!!.jsonPrimitive.content,_state.value.options));load()}catch(e:Exception){fail(e)}};private fun fail(e:Exception){_state.value=_state.value.copy(loading=false,saving=false,error=if(e is IOException)"Connection interrupted. Your inputs were kept; reload current status before retrying." else if(e is ApiException)e.serverMessage?:"Project action rejected by server." else "Project action rejected by server.")}}
